//! Curated and multi-epoch minor-body osculating elements.
//!
//! Generated numeric data from `libephemeris/minor_bodies.py` and
//! `libephemeris/multi_epoch_data.py` at
//! `37ffb0555b7a9f5083b4f1b6dc1a0f10feeb85fa` (v3.2.1).
//! The 37 curated rows originate from JPL SBDB (2025-Nov-27). The 2916
//! multi-epoch rows are 36 bodies at 81 ten-year nodes across 1650–2450,
//! fitted to JPL Horizons SPK type21 states by
//! `scripts/generate_multi_epoch_elements.py`. Bennu has only its curated epoch.
//!
//! Semimajor axes use AU, eccentricities are dimensionless, orbital angles
//! degrees and mean motions degrees/day. Reference epochs are Julian days;
//! original curated metadata labels them TDB, while the original element type
//! labels them TT. Propagation and scale conversion belong to the caller.
//! Keplerian accuracy degrades away from the osculating epoch through neglected
//! perturbations (typically 10–50 arcsec/year); use updated elements or an
//! appropriate numerical ephemeris when that matters. Keep generated values
//! unchanged; unknown-body and range policy belong to the consumers.

//! Large-precision literals: the transcribed element values intentionally
//! carry full data precision; the `excessive_precision` lint is allowed
//! for this file (values must never be edited).
#![allow(clippy::excessive_precision)]

use crate::constants::*;

/// One curated single-epoch element row.
///
/// Field contract: `a` is the semi-major axis in AU; `e` is
/// dimensionless eccentricity; `i_deg`, `omega_deg` (argument of
/// perihelion), `node_deg` (longitude of ascending node) and `m0_deg` (mean
/// anomaly at epoch) are in degrees; `n_deg_day` is mean motion in
/// degrees/day; `epoch` is the reference epoch as Julian Day. Elements are osculating at `epoch`. `body_id` is the model
/// dict key, carried so rows keep their identity.
#[derive(Clone, Copy, Debug)]
pub(crate) struct MinorBodyRow {
    /// numerical catalog key identifying the body.
    pub body_id: i32,
    /// Body name.
    pub name: &'static str,
    /// Reference epoch as Julian Day (see the struct-level scale note).
    pub epoch: f64,
    /// Semi-major axis in AU.
    pub a: f64,
    /// Dimensionless eccentricity.
    pub e: f64,
    /// Inclination to the ecliptic in degrees.
    pub i_deg: f64,
    /// Argument of perihelion in degrees.
    pub omega_deg: f64,
    /// Longitude of ascending node in degrees.
    pub node_deg: f64,
    /// Mean anomaly at epoch in degrees.
    pub m0_deg: f64,
    /// Mean motion in degrees/day.
    pub n_deg_day: f64,
}

/// The 37 curated base rows in catalog row order.
///
/// Rows are osculating at their epoch (JD 2461000.5 TDB per the model
/// header); accuracy degrades ~10-50 arcsec/year from secular perturbations,
/// so dates >10 years from epoch should use updated elements. Exception:
/// Bennu uses epoch 2459000.5 from the OSIRIS-REx mission kernel
/// (`bennu_refdrmc_v1.bsp`, heliocentric segment, 2015-2023 coverage),
/// because a Keplerian propagation across Earth close approaches cannot
/// carry an Apollo PHA state.
