/// Gaussian `k^2` solar mass parameter, IAU-1976 J2000 obliquity, IAU-2012
/// exact AU). Bennu is excluded: no compatible heliocentric J2000 type-21
/// source kernel covered the grid, so only its curated epoch above applies.
